-- ============================================================
-- prcp_data_basic 基础数据（基于 LCR.xlsx 当前余额）
-- 数据日期: 2025-12-31
-- 方案: ZX_COA (scheme_id=1)
-- 节点数: 57
-- 桶分配：当前余额 → orig_m1 + rem_m1（30 天内到期）
-- ============================================================

SET NAMES utf8mb4;
DELETE FROM prcp_data_basic WHERE data_date = '2025-12-31';


-- ============================================================
-- 验证
-- ============================================================
SELECT COUNT(*) AS total_cnt, SUM(current_balance) AS total_balance
FROM prcp_data_basic WHERE data_date = '2025-12-31';

SELECT category, COUNT(*) AS cnt, SUM(current_balance) AS total
FROM prcp_data_basic WHERE data_date = '2025-12-31' GROUP BY category;

SELECT node_level, COUNT(*) AS cnt, SUM(current_balance) AS total
FROM prcp_data_basic WHERE data_date = '2025-12-31' GROUP BY node_level ORDER BY node_level;

SELECT node_code, node_name, is_leaf, current_balance, hqla_factor, asf_rsf
FROM prcp_data_basic WHERE data_date = '2025-12-31' AND current_balance > 0
ORDER BY node_code LIMIT 10;